1	import * as THREE from "three";
2	import { BlockId } from "./blocks";
3	import { VoxelWorld } from "./voxelWorld";
4	import { doorBounds, isDoorBlock } from "./doors";
5	import { isRedstoneOverlay } from "./redstone";
6	
7	export type RaycastResult = {
8	  hit: THREE.Vector3;
9	  previous: THREE.Vector3;
10	  /** Ray parameter where the ray enters the hit cell (0 when the origin cell is already solid). */
11	  distance: number;
12	};
13	
14	// DDA voxel traversal. `previous` is the last empty cell before the hit —
15	// face-adjacent to it, never diagonal — which is where placed blocks go.
16	export function voxelRaycast(world: VoxelWorld, origin: THREE.Vector3, direction: THREE.Vector3, maxDist = 6): RaycastResult | null {
17	  const dir = direction.clone().normalize();
18	  const pos = origin.clone();
19	
20	  let x = Math.floor(pos.x);
21	  let y = Math.floor(pos.y);
22	  let z = Math.floor(pos.z);
23	
24	  const stepX = dir.x > 0 ? 1 : -1;
25	  const stepY = dir.y > 0 ? 1 : -1;
26	  const stepZ = dir.z > 0 ? 1 : -1;
27	
28	  const invDx = Math.abs(1 / (dir.x || 1e-6));
29	  const invDy = Math.abs(1 / (dir.y || 1e-6));
30	  const invDz = Math.abs(1 / (dir.z || 1e-6));
31	
32	  let tMaxX = ((stepX > 0 ? x + 1 : x) - pos.x) / (dir.x || 1e-6);
33	  let tMaxY = ((stepY > 0 ? y + 1 : y) - pos.y) / (dir.y || 1e-6);
34	  let tMaxZ = ((stepZ > 0 ? z + 1 : z) - pos.z) / (dir.z || 1e-6);
35	  if (tMaxX < 0) tMaxX += invDx;
36	  if (tMaxY < 0) tMaxY += invDy;
37	  if (tMaxZ < 0) tMaxZ += invDz;
38	
39	  let t = 0;
40	  let previous = new THREE.Vector3(x, y, z);
41	
42	  while (t <= maxDist) {
43	    if (world.isSolid(x, y, z)) return { hit: new THREE.Vector3(x, y, z), previous, distance: t };
44	    previous = new THREE.Vector3(x, y, z);
45	
46	    if (tMaxX < tMaxY) {
47	      if (tMaxX < tMaxZ) {
48	        x += stepX;
49	        t = tMaxX;
50	        tMaxX += invDx;
51	      } else {
52	        z += stepZ;
53	        t = tMaxZ;
54	        tMaxZ += invDz;
55	      }
56	    } else if (tMaxY < tMaxZ) {
57	      y += stepY;
58	      t = tMaxY;
59	      tMaxY += invDy;
60	    } else {
61	      z += stepZ;
62	      t = tMaxZ;
63	      tMaxZ += invDz;
64	    }
65	  }
66	
67	  return null;
68	}
69	
70	/**
71	 * Marches the ray and returns the first Water cell whose cell above is Air — the
72	 * water *surface* the player is aiming at (for casting a fishing bobber). Returns
73	 * null if a solid block is hit first (you can't fish through terrain) or no such
74	 * water cell is reached within `maxDist`. Mirrors `voxelRaycast`'s DDA; the normal
75	 * raycast can't be reused because it treats water as empty and passes through it.
76	 */
77	export function waterSurfaceRaycast(world: VoxelWorld, origin: THREE.Vector3, direction: THREE.Vector3, maxDist = 7): THREE.Vector3 | null {
78	  const dir = direction.clone().normalize();
79	  const pos = origin.clone();
80	
81	  let x = Math.floor(pos.x);
82	  let y = Math.floor(pos.y);
83	  let z = Math.floor(pos.z);
84	
85	  const stepX = dir.x > 0 ? 1 : -1;
86	  const stepY = dir.y > 0 ? 1 : -1;
87	  const stepZ = dir.z > 0 ? 1 : -1;
88	
89	  const invDx = Math.abs(1 / (dir.x || 1e-6));
90	  const invDy = Math.abs(1 / (dir.y || 1e-6));
91	  const invDz = Math.abs(1 / (dir.z || 1e-6));
92	
93	  let tMaxX = ((stepX > 0 ? x + 1 : x) - pos.x) / (dir.x || 1e-6);
